-- ── P7 : permissions du rôle "rh" ──────────────────────────────────────────
INSERT INTO public.role_permissions (role, permission_key, granted, tenant_id)
SELECT 'rh'::public.app_role, k, true, NULL
FROM (VALUES
  ('ia.ask'),('clients.manage'),('dossiers.view'),('dossiers.create'),('dossiers.edit'),
  ('documents.upload'),('documents.generate'),('documents.analyze'),
  ('workflows.run'),('veille.view'),('employees.manage'),('sites.manage')
) AS t(k)
WHERE NOT EXISTS (
  SELECT 1 FROM public.role_permissions rp
  WHERE rp.role = 'rh'::public.app_role AND rp.permission_key = t.k AND rp.tenant_id IS NULL
);

